// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(uint64 numberVal, uint64 timestampVal, uint256 basefeeVal) public {
        vm.prank(0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        c.setL1BlockValues(
            numberVal,
            timestampVal,
            basefeeVal,
            bytes32(uint256(1)),
            0,
            bytes32(0),
            0,
            0
        );
        assertEq(c.number(), numberVal);
    }
}
